draw:
var lc = 0.002426;
var th = p.theta * Math.PI / 180;
var dl = lc * (1 - Math.cos(th));
var lam = p.lam;
var lp = lam + dl;
var K = 1240 / lam - 1240 / lp;   // eV
var alpha = (1240 / lam) / 511000.0;
var phi = Math.atan(1 / ((1 + alpha) * Math.tan(th / 2 + 1e-9))) * 180 / Math.PI;

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.lineWidth = 1.6;
var cx = W * 0.46, cy = H * 0.52;
var L = Math.min(W, H) * 0.42;

// incident photon
ctx.strokeStyle = C.accent;
ctx.beginPath(); ctx.moveTo(cx - L * 1.25, cy); ctx.lineTo(cx - 12, cy); ctx.stroke();
ctx.beginPath();
ctx.moveTo(cx - 10, cy); ctx.lineTo(cx - 20, cy - 4); ctx.lineTo(cx - 20, cy + 4);
ctx.closePath(); ctx.fillStyle = C.accent; ctx.fill();
ctx.textAlign = "left";
ctx.fillText("incoming photon, " + lam.toFixed(4) + " nm", 4, cy - 10);

// electron at rest
ctx.fillStyle = C.ink;
ctx.beginPath(); ctx.arc(cx, cy, 5, 0, Math.PI * 2); ctx.fill();
ctx.textAlign = "center";
ctx.fillText("electron at rest", cx, cy - 12);

// dashed original direction
ctx.strokeStyle = C.rule;
ctx.setLineDash([3, 4]);
ctx.beginPath(); ctx.moveTo(cx, cy); ctx.lineTo(cx + L * 1.1, cy); ctx.stroke();
ctx.setLineDash([]);

// scattered photon
var sx = cx + L * Math.cos(th), sy = cy - L * Math.sin(th);
ctx.strokeStyle = C.accent;
ctx.beginPath(); ctx.moveTo(cx, cy); ctx.lineTo(sx, sy); ctx.stroke();
ctx.beginPath();
ctx.moveTo(sx, sy);
ctx.lineTo(sx - 10 * Math.cos(th) - 4 * Math.sin(th), sy + 10 * Math.sin(th) - 4 * Math.cos(th));
ctx.lineTo(sx - 10 * Math.cos(th) + 4 * Math.sin(th), sy + 10 * Math.sin(th) + 4 * Math.cos(th));
ctx.closePath(); ctx.fillStyle = C.accent; ctx.fill();
ctx.textAlign = sx > cx ? "left" : "right";
ctx.fillText("scattered photon, " + lp.toFixed(4) + " nm", sx + (sx > cx ? 6 : -6), sy - 6);

// recoil electron
var rp = phi * Math.PI / 180;
var ex = cx + L * 0.72 * Math.cos(rp), ey = cy + L * 0.72 * Math.sin(rp);
ctx.strokeStyle = C.figure;
ctx.beginPath(); ctx.moveTo(cx, cy); ctx.lineTo(ex, ey); ctx.stroke();
ctx.beginPath();
ctx.moveTo(ex, ey);
ctx.lineTo(ex - 10 * Math.cos(rp) - 4 * Math.sin(rp), ey - 10 * Math.sin(rp) + 4 * Math.cos(rp));
ctx.lineTo(ex - 10 * Math.cos(rp) + 4 * Math.sin(rp), ey - 10 * Math.sin(rp) - 4 * Math.cos(rp));
ctx.closePath(); ctx.fillStyle = C.figure; ctx.fill();
ctx.textAlign = "left";
ctx.fillText("recoil electron", ex + 6, ey + 12);

// angle arcs
ctx.strokeStyle = C.faint;
ctx.beginPath(); ctx.arc(cx, cy, 34, -th, 0); ctx.stroke();
ctx.fillStyle = C.faint;
ctx.textAlign = "left";
ctx.fillText("theta = " + p.theta.toFixed(0) + " deg", cx + 38, cy - 16);
ctx.beginPath(); ctx.arc(cx, cy, 26, 0, rp); ctx.stroke();
ctx.fillText("phi = " + phi.toFixed(0) + " deg", cx + 30, cy + 26);

out.note = "shift " + dl.toFixed(5) + " nm, scattered wavelength " + lp.toFixed(5)
  + " nm, electron gains " + K.toFixed(1) + " eV";
